Hi All,<div>I&#39;m having an issue with an unregistered distribution using the parallel library. The non-parallel version works fine. I have put below two self-contained code examples - the first uses a custom pdf on a single core and works fine. The second uses the parallel library and gives an error about the pdf not being registered - I think I have registered it, so I guess I&#39;ve not done it properly? </div><div><br></div><div>Any thoughts or help much appreciated! thanks.<div>best wishes</div><div>Fraser</div><div><br></div><div>##################</div><div>The Error:</div><div>##################</div><div>Error in checkForRemoteErrors(val) : 
  one node produced an error: In sizeAssignAfterRecursing: &#39;rmysde&#39; is not available or its output type is unknown.
 This occurred for: model_Observation2_latent[getNodeFunctionIndexedInfo(ARG1_INDEXEDNODEINFO__,1)] &lt;&lt;- rmysde(=1,x0=model_Observation1_latent[getNodeFunctionIndexedInfo(ARG1_INDEXEDNODEINFO__,1)],t=model_lifted_Time2_oBi_cB_minus_Time1_oBi_cB_L11[getNodeFunctionIndexedInfo(ARG1_INDEXEDNODEINFO__,1)],alpha=model_a[1],K=model_K[1],sigma=model_sigma3[1])
 This was part of the call:  {
  model_Observation2_latent[getNodeFunctionIndexedInfo(ARG1_INDEXEDNODEINFO__,1)] &lt;&lt;- rmysde(=1,x0=model_Observation1_latent[getNodeFunctionIndexedInfo(ARG1_INDEXEDNODEINFO__,1)],t=model_lifted_Time2_oBi_cB_minus_Time1_oBi_cB_L11[getNodeFunctionIndexedInfo(ARG1_INDEXEDNODEINFO__,1)],alpha=model_a[1],K=model_K[1],sigma=model_sigma3[1])
}  <br></div><div><br></div><div>############################################</div><div># self-contained code example - the first part runs fine, the second part not</div><div><div>###############################################################################################################</div><div># SINGLE CORE VERSION</div><div># works ok</div><div>###############################################################################################################</div><div><br></div><div>rm(list=ls());</div><div>############## DATA</div><div>data1 &lt;-</div><div>structure(list(ID = c(38L, 38L, 38L, 38L, 38L, 38L, 38L, 38L, </div><div>38L, 38L, 38L, 38L, 38L, 38L), Time1 = c(11, 12, 13, 14, 17, </div><div>18, 19, 20, 25, 26, 27, 28, 32, 33), Observation1 = c(109.08, </div><div>161.68000000000001, 275.70999999999998, 231.21000000000001, 299.63, </div><div>455.69, 540, 713.75999999999999, 723.82000000000005, 819.04999999999995, </div><div>791.57000000000005, 681.34000000000003, 999.44000000000005, 1067.6500000000001</div><div>), ID = c(38L, 38L, 38L, 38L, 38L, 38L, 38L, 38L, 38L, 38L, 38L, </div><div>38L, 38L, 38L), Time2 = c(12, 13, 14, 17, 18, 19, 20, 25, 26, </div><div>27, 28, 32, 33, 34), Observation2 = c(161.68000000000001, 275.70999999999998, </div><div>231.21000000000001, 299.63, 455.69, 540, 713.75999999999999, </div><div>723.82000000000005, 819.04999999999995, 791.57000000000005, 681.34000000000003, </div><div>999.44000000000005, 1067.6500000000001, 1132.1600000000001)), class = &quot;data.frame&quot;, row.names = 331:344)</div><div><br></div><div><br></div><div>###########################################</div><div>library(nimble, warn.conflicts = FALSE)</div><div>###########################################</div><div><br></div><div>## custom density dXXXX</div><div>dmysde &lt;- nimbleFunction(</div><div>    run = function(x = double(0),                  # random variable value</div><div>                   x0 = double(0, default = 0),</div><div>                   t = double(0, default = 0),</div><div>                   alpha = double(0, default = 0),    </div><div>                   K = double(0, default = 0),</div><div>                   sigma = double(0, default = 1), # standard deviation</div><div>                   </div><div>                   log = integer(0, default = 0)) {</div><div>                         returnType(double(0))</div><div>                         # log pdf</div><div>                         logProb &lt;- (1/2)*(</div><div>                                            -log(2*pi*t) - 2*log(x) - ((</div><div>                                                  ((t*sigma^2)/2) - log(K) + log(x) + </div><div>                                                  (exp(-t*alpha))*(log(K) - log(x0)))^2)/(t*sigma^2) - </div><div>                                          2*log(sigma)</div><div>                                          )</div><div>        if(log) return(logProb)</div><div>        else return(exp(logProb)) </div><div>    })</div><div><br></div><div>## this is not strictly needed but here as a check - the mcmc sampler should generate the variate</div><div>## and so a stop() is used here to catch if this is used, in which case we need to switch sampler type</div><div>  rmysde &lt;- nimbleFunction(</div><div>    run = function(n = integer(0),</div><div>                   x0 = double(0, default = 0),</div><div>                    t = double(0, default = 0),</div><div>                   alpha = double(0, default = 0),    </div><div>                   K = double(0, default = 0),</div><div>                   sigma = double(0, default = 1)) {</div><div>                                      stop(&#39;rmynorm should never be run&#39;)</div><div>                                      returnType(double(0))</div><div>                             return(0)</div><div>    })</div><div>deregisterDistributions(&#39;dmysde&#39;)</div><div>registerDistributions(&#39;dmysde&#39;)</div><div><br></div><div>code &lt;- nimbleCode({</div><div>  </div><div>  sigma1 ~ dunif(0, 1000)</div><div>  sigma2 ~ dunif(0, 1000)</div><div>  sigma3 ~ dunif(0, 1000)</div><div>  </div><div>  a ~ dnorm(0,sd=1000)</div><div>  K ~ dnorm(0,sd=1000)</div><div>  mu_t ~ dnorm(0,sd=1000)</div><div>  sigma_t ~ dunif(0, 1000)</div><div>  </div><div>  for(i in 1:n) {</div><div>     </div><div>      Observation1_latent[i]  ~ dnorm(mu_t,sd=sigma_t); # note = precision</div><div>      Observation1[i] ~ dnorm(Observation1_latent[i],sd=sigma1); # note = precision</div><div> </div><div>      Observation2_latent[i] ~ dmysde(x0=Observation1_latent[i],t=Time2[i]-Time1[i],alpha=a,K=K,sigma=sigma3); # note sigma3=sd </div><div>      </div><div>      Observation2[i]~dnorm(Observation2_latent[i],sd=sigma2); # note precision</div><div>     </div><div>       }</div><div>  </div><div>})</div><div><br></div><div>constants &lt;- list(n = nrow(data1))</div><div>data &lt;- list(Observation1 = data1$Observation1,Observation2 = data1$Observation2,</div><div>             Time1 = data1$Time1,Time2=data1$Time2)</div><div>inits &lt;- list(a=0.1,K=1000,sigma2=10,sigma3=0.1,sigma1=0.1,mu_t=0.1,sigma_t=1.0,</div><div>              Observation1_latent=rep(0.1,nrow(data1)),</div><div>              Observation2_latent=rep(0.1,nrow(data1))</div><div>              )</div><div>              </div><div><br></div><div>model &lt;- nimbleModel(code, constants = constants, data = data1, inits = inits) # build model</div><div><br></div><div>myMCMCconf &lt;- configureMCMC(model) </div><div><br></div><div>print(myMCMCconf);</div><div>myMCMC&lt;-buildMCMC(myMCMCconf)</div><div><br></div><div>Cmodel &lt;- compileNimble(model,resetFunctions = TRUE,showCompilerOutput = FALSE)</div><div>CmodelMCMC &lt;- compileNimble(myMCMC, project = Cmodel,resetFunctions = TRUE,showCompilerOutput = FALSE)</div><div><br></div><div>seeds&lt;-1;</div><div>MCMCsamples &lt;- runMCMC(CmodelMCMC, niter = 100,thin=1,nchains=1,setSeed=seeds,</div><div>                   samplesAsCodaMCMC = FALSE)</div><div><br></div><div><br></div><div>###############################################################################################################</div><div># PARALLEL VERSION</div><div># fails! on missing rmydist function</div><div>###############################################################################################################</div><div>rm(list=ls())</div><div>############## DATA</div><div>data1 &lt;-</div><div>structure(list(ID = c(38L, 38L, 38L, 38L, 38L, 38L, 38L, 38L, </div><div>38L, 38L, 38L, 38L, 38L, 38L), Time1 = c(11, 12, 13, 14, 17, </div><div>18, 19, 20, 25, 26, 27, 28, 32, 33), Observation1 = c(109.08, </div><div>161.68000000000001, 275.70999999999998, 231.21000000000001, 299.63, </div><div>455.69, 540, 713.75999999999999, 723.82000000000005, 819.04999999999995, </div><div>791.57000000000005, 681.34000000000003, 999.44000000000005, 1067.6500000000001</div><div>), ID = c(38L, 38L, 38L, 38L, 38L, 38L, 38L, 38L, 38L, 38L, 38L, </div><div>38L, 38L, 38L), Time2 = c(12, 13, 14, 17, 18, 19, 20, 25, 26, </div><div>27, 28, 32, 33, 34), Observation2 = c(161.68000000000001, 275.70999999999998, </div><div>231.21000000000001, 299.63, 455.69, 540, 713.75999999999999, </div><div>723.82000000000005, 819.04999999999995, 791.57000000000005, 681.34000000000003, </div><div>999.44000000000005, 1067.6500000000001, 1132.1600000000001)), class = &quot;data.frame&quot;, row.names = 331:344)</div><div><br></div><div>library(parallel)</div><div><br></div><div>Nnodes&lt;-1;</div><div><br></div><div>this_cluster &lt;- makeCluster(Nnodes)</div><div><br></div><div>run_MCMC_allcode &lt;- function(seeds,dat) {</div><div>###########################################</div><div>library(nimble, warn.conflicts = FALSE)</div><div>###########################################</div><div><br></div><div>## custom density dXXXX</div><div>dmysde &lt;- nimbleFunction(</div><div>    run = function(x = double(0),                  # random variable value</div><div>                   x0 = double(0, default = 0),</div><div>                   t = double(0, default = 0),</div><div>                   alpha = double(0, default = 0),    </div><div>                   K = double(0, default = 0),</div><div>                   sigma = double(0, default = 1), # standard deviation</div><div>                   </div><div>                   log = integer(0, default = 0)) {</div><div>                         returnType(double(0))</div><div>                         # log pdf</div><div>                         logProb &lt;- (1/2)*(</div><div>                                            -log(2*pi*t) - 2*log(x) - ((</div><div>                                                  ((t*sigma^2)/2) - log(K) + log(x) + </div><div>                                                  (exp(-t*alpha))*(log(K) - log(x0)))^2)/(t*sigma^2) - </div><div>                                          2*log(sigma)</div><div>                                          )</div><div>        if(log) return(logProb)</div><div>        else return(exp(logProb)) </div><div>    })</div><div><br></div><div>## this is not strictly needed but here as a check - the mcmc sampler should generate the variate</div><div>## and so a stop() is used here to catch if this is used, in which case we need to switch sampler type</div><div>  rmysde &lt;- nimbleFunction(</div><div>    run = function(n = integer(0),</div><div>                   x0 = double(0, default = 0),</div><div>                    t = double(0, default = 0),</div><div>                   alpha = double(0, default = 0),    </div><div>                   K = double(0, default = 0),</div><div>                   sigma = double(0, default = 1)) {</div><div>                                      stop(&#39;rmynorm should never be run&#39;)</div><div>                                      returnType(double(0))</div><div>                             return(0)</div><div>    })</div><div>  </div><div>deregisterDistributions(&#39;dmysde&#39;)</div><div><br></div><div>registerDistributions(list(</div><div>    dmysde = list(</div><div>        BUGSdist = &quot;dmysde(x0,t,alpha,K,sigma)&quot;,</div><div>        types = c(&#39;value = double(0)&#39;, &#39;x0=double(0)&#39;,&#39;t=double(0)&#39;,&#39;alpha=double(0)&#39;,&#39;K=double(0)&#39;,&#39;sigma=double(0)&#39;)</div><div>        )</div><div>    ))</div><div><br></div><div><br></div><div>code &lt;- nimbleCode({</div><div>  </div><div>  sigma1 ~ dunif(0, 1000)</div><div>  sigma2 ~ dunif(0, 1000)</div><div>  sigma3 ~ dunif(0, 1000)</div><div>  </div><div>  a ~ dnorm(0,sd=1000)</div><div>  K ~ dnorm(0,sd=1000)</div><div>  </div><div>   mu_t ~ dnorm(0,sd=1000)</div><div>  sigma_t ~ dunif(0, 1000)</div><div> </div><div>  for(i in 1:n) {</div><div>     </div><div>      Observation1_latent[i]  ~ dnorm(mu_t,sd=sigma_t); # note = precision</div><div>      Observation1[i] ~ dnorm(Observation1_latent[i],sd=sigma1); # note = precision</div><div> </div><div>      Observation2_latent[i] ~ dmysde(x0=Observation1_latent[i],t=Time2[i]-Time1[i],alpha=a,K=K,sigma=sigma3); # note sigma3=sd </div><div>      </div><div>      Observation2[i]~dnorm(Observation2_latent[i],sd=sigma2); # note precision</div><div>     </div><div>       }</div><div>  </div><div>})</div><div><br></div><div>data1=dat[[1]];</div><div>constants &lt;- list(n = nrow(data1))</div><div>data &lt;- list(Observation1 = data1$Observation1,Observation2 = data1$Observation2,</div><div>             Time1 = data1$Time1,Time2=data1$Time2)</div><div>inits &lt;- list(a=0.1,K=1000,sigma2=10,sigma3=0.1,sigma1=0.1,mu_t=0.1,sigma_t=1.0,</div><div>              Observation1_latent=rep(0.1,nrow(data1)),</div><div>              Observation2_latent=rep(0.1,nrow(data1))</div><div>              )</div><div>              </div><div><br></div><div>model &lt;- nimbleModel(code, constants = constants, data = data1, inits = inits) # build model</div><div><br></div><div>myMCMCconf &lt;- configureMCMC(model) </div><div><br></div><div>print(myMCMCconf);</div><div>myMCMC&lt;-buildMCMC(myMCMCconf)</div><div><br></div><div>Cmodel &lt;- compileNimble(model,resetFunctions = TRUE,showCompilerOutput = FALSE)</div><div>CmodelMCMC &lt;- compileNimble(myMCMC, project = Cmodel,resetFunctions = TRUE,showCompilerOutput = FALSE)</div><div><br></div><div>MCMCsamples &lt;- runMCMC(CmodelMCMC, niter = 5000000,thin=500,nchains=4,setSeed=seeds,</div><div>                   samplesAsCodaMCMC = FALSE)</div><div><br></div><div>return(MCMCsamples);</div><div>}</div><div><br></div><div><br></div><div>chain_output &lt;- parLapply(cl = this_cluster, X = 1:Nnodes, ## NOTE this is the seeds argument!</div><div>                          fun = run_MCMC_allcode, </div><div>                          dat=list(data1) # this is one extra argument</div><div>                          )</div><div><br></div><div># It&#39;s good practice to close the cluster when you&#39;re done with it.</div><div>stopCluster(this_cluster)</div></div><div><br></div><div><br></div><div><br></div><div><br></div><div><br></div><div><br></div><div><br></div></div>
